/*
 * STM32CubeIDE example for NUCLEO-F446RE, HAL F4.
 * Add this .c file to Core/Src and lumos_protocol.c to Core/Src.
 * Add firmware/stm32/include to compiler include paths.
 * Enable USART2 asynchronous TX at 115200 8N1 in CubeMX.
 * Call lumos_telemetry_tick(&huart2) from generated main.c's while(1).
 * Do not modify CubeMX-generated peripheral initialization functions.
 */
#include "main.h"  /* Generated by STM32CubeMX; not available in native build. */
#include "lumos_protocol.h"

#include <stdint.h>

void lumos_telemetry_tick(UART_HandleTypeDef *uart)
{
    static uint32_t last_sent = 0u;
    static uint32_t sequence = 0u;
    char line[LUMOS_FRAME_CAPACITY];
    const uint32_t now = HAL_GetTick();
    int count;
    /* Unsigned subtraction supports the 32-bit SysTick millisecond wraparound. */
    if ((uint32_t)(now - last_sent) < 1000u) return;
    last_sent = now;

    /*
     * Temperature and VDD are intentionally NA until real ADC sampling,
     * calibration, and error handling have been added for the target board.
     * No invented sensor readings or fabricated health assessments.
     */
    count = lumos_encode("nucleo-f446re", sequence++, now,
                         LUMOS_MISSING_VDD, LUMOS_MISSING_TEMPERATURE,
                         "unknown", line, sizeof(line));
    if (count > 0 && uart != NULL) {
        (void)HAL_UART_Transmit(uart, (uint8_t *)line, (uint16_t)count, 100u);
    }
}
